body:
Upgrading a project from 2.4.5 to 2.5.0 and a test started failing. I hacked up a simplified test case to reproduce:

```cs       
        [Fact]
        public async void Reproducing_test()
        {
            var expected1 = new Dictionary<string, List<string>>
            {
                ["toAddresses"] = new List<string> { "test1@example.com" },
                ["ccAddresses"] = new List<string> { "test2@example.com" },
            };
            var actual1 = new Dictionary<string, List<string>>();
            actual1["toAddresses"] = expected1["toAddresses"];
            actual1["ccAddresses"] = expected1["ccAddresses"];

            Assert.Equal(expected1, actual1);

            var expected2 = new Dictionary<string, List<string>>
            {
                ["toAddresses"] = new List<string> { "test1@example.com" },
                ["ccAddresses"] = new List<string> { "test2@example.com" },
            };
            var actual2 = new Dictionary<string, List<string>>
            {
                ["toAddresses"] = new List<string> { "test1@example.com" },
                ["ccAddresses"] = new List<string> { "test2@example.com" },
            };

            Assert.Equal(expected2, actual2);
        }
```


The second assertion fails with:

>  Message: 
> Assert.Equal() Failure: Dictionaries differ
> Expected: [["toAddresses"] = ["test1@example.com"], ["ccAddresses"] = ["test2@example.com"]]
> Actual:   [["toAddresses"] = ["test1@example.com"], ["ccAddresses"] = ["test2@example.com"]]

Previously both would pass. It seems that Assert.Equals() no longer does deep equality for Dictionary values, at least for the List<string> type. It appears to be using reference equality instead. I didn't see any documentation about this behavior change in the release notes so I'm assuming that it is a regression.
